import{_ as s}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as l,D as g,o as r,c,I as m,w as d,k as a,a as h,R as _,b as u,e as p}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const P=JSON.parse('{"title":"RAG、Memory 与 Context Engineering","description":"","frontmatter":{"title":"RAG、Memory 与 Context Engineering","author":"阿源","date":"2026/10/07 00:00","categories":["Agent 开发"],"tags":["RAG","Memory","Context Engineering"],"status":"预览版导航"},"headers":[],"relativePath":"courses/agent/01-项目与知识库导航/05-RAG记忆与上下文工程.md","filePath":"courses/agent/01-项目与知识库导航/05-RAG记忆与上下文工程.md","lastUpdated":1791349179000}'),x={name:"courses/agent/01-项目与知识库导航/05-RAG记忆与上下文工程.md"},f=a("h1",{id:"rag、memory-与-context-engineering",tabindex:"-1"},[h("RAG、Memory 与 Context Engineering "),a("a",{class:"header-anchor",href:"#rag、memory-与-context-engineering","aria-label":'Permalink to "RAG、Memory 与 Context Engineering"'},"​")],-1),A=_('<p>RAG、Memory 和 Context Engineering 都在影响模型输入，但解决的问题不同：RAG 负责从外部资料取证，Memory 负责跨回合保留经过筛选的信息，Context Engineering 负责在当前预算内组装可用上下文。先读 <a href="/courses/agent/05-状态上下文会话与记忆/01-State与Context">05 State、Context、Session 与 Memory</a>，再进入 <a href="/courses/agent/08-RAG与上下文工程/01-RAG管线与适用边界">08 RAG 与 Context Engineering</a>。</p><h2 id="llamaindex-rag-组件文档" tabindex="-1">LlamaIndex RAG 组件文档 <a class="header-anchor" href="#llamaindex-rag-组件文档" aria-label="Permalink to &quot;LlamaIndex RAG 组件文档&quot;">​</a></h2><p>官方入口：<a href="https://docs.llamaindex.ai/en/stable/module_guides/querying/" target="_blank" rel="noreferrer">Querying 文档</a> · <a href="https://github.com/run-llama/llama_index" target="_blank" rel="noreferrer">GitHub</a></p><ul><li><strong>解决的问题</strong>：把文档摄取、索引、检索、重排和回答组装为可替换的 RAG 管线。</li><li><strong>推荐学习内容</strong>：只用作组件地图，先理解无框架 RAG，再按 ingestion、retriever、reranker、citation 查阅。</li><li><strong>前置知识</strong>：第 05、08 章；文本切分与检索直觉。</li><li><strong>学习阶段</strong>：进阶。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：Querying、Retrievers、Node parsers、Evaluation。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：检索结果与上下文组装可作为 dsh tool/Skill 输出进入 driver context，但框架不决定 dsh session。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="mem0" tabindex="-1">Mem0 <a class="header-anchor" href="#mem0" aria-label="Permalink to &quot;Mem0&quot;">​</a></h2><p>官方入口：<a href="https://github.com/mem0ai/mem0" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://docs.mem0.ai/" target="_blank" rel="noreferrer">文档</a></p><ul><li><strong>解决的问题</strong>：提供长期记忆提取、存储和召回的实现参考，帮助区分会话状态与持久记忆。</li><li><strong>推荐学习内容</strong>：重点阅读 memory extraction、scoping、更新和删除策略；先设计隔离与保留策略，再尝试集成。</li><li><strong>前置知识</strong>：State、Session、Memory；第 05 章。</li><li><strong>学习阶段</strong>：生产工程。</li><li><strong>阅读深度</strong>：案例参考。</li><li><strong>推荐目录/文章</strong>：memory model、add/search/update/delete、privacy and isolation、tests。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：长期记忆属于 dsh Session 之外的持久化插件，必须明确租户、用户和会话作用域。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="langchain-文档-context-engineering" tabindex="-1">LangChain 文档：Context Engineering <a class="header-anchor" href="#langchain-文档-context-engineering" aria-label="Permalink to &quot;LangChain 文档：Context Engineering&quot;">​</a></h2><p>官方入口：<a href="https://docs.langchain.com/oss/python/langchain/context-engineering" target="_blank" rel="noreferrer">Context engineering 文档</a> · <a href="https://docs.langchain.com/" target="_blank" rel="noreferrer">LangChain 文档</a></p><ul><li><strong>解决的问题</strong>：整理模型输入上下文、工具结果、状态和记忆的工程化边界。</li><li><strong>推荐学习内容</strong>：用来建立术语地图，回到本课程的无框架 Python 示例验证每个概念。</li><li><strong>前置知识</strong>：第 02–05 章。</li><li><strong>学习阶段</strong>：入门。</li><li><strong>阅读深度</strong>：专题查阅。</li><li><strong>推荐目录/文章</strong>：runtime context、state、memory、context shaping。</li><li><strong>与 DeepSeek Harness 对应关系</strong>：Context shaping 对应 dsh driver 在每一轮把 Session、Skill 和 tool result 拼入模型输入的责任。</li><li><strong>查看日期</strong>：2026-10-07。</li></ul><h2 id="选型与安全检查" tabindex="-1">选型与安全检查 <a class="header-anchor" href="#选型与安全检查" aria-label="Permalink to &quot;选型与安全检查&quot;">​</a></h2><ul><li>资料是实时、私有或需要引用时，考虑 RAG；先做权限过滤和证据追踪，再做 embedding 优化。</li><li>用户偏好或跨会话事实需要保存时，考虑 Memory；为用户、租户、会话设置独立 scope，提供删除和过期策略。</li><li>当前回合信息超预算时，先做 context projection、压缩和摘要；不要把所有历史原文无条件塞回模型。</li><li>任何来自检索或记忆的文本都可能包含指令注入，必须与系统规则和工具权限分开处理。</li></ul>',12);function y(e,C,b,k,R,G){const o=s,i=g("ClientOnly");return r(),c("div",null,[f,m(i,null,{default:d(()=>{var t,n;return[(((t=e.$frontmatter)==null?void 0:t.aside)??!0)&&(((n=e.$frontmatter)==null?void 0:n.showArticleMetadata)??!0)?(r(),u(o,{key:0,article:e.$frontmatter},null,8,["article"])):p("",!0)]}),_:1}),A])}const q=l(x,[["render",y]]);export{P as __pageData,q as default};
